(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[806],{6475:(n,e,t)=>{Promise.resolve().then(t.bind(t,7109))},7109:(n,e,t)=>{"use strict";t.r(e),t.d(e,{default:()=>l});var r=t(5155),a=t(8883),s=t(6965),o=t(1452),c=t(9981);function l(){let n=(0,a.r)();return(0,r.jsxs)(s.default,{children:[(0,r.jsx)(o.default,{variant:"h4",sx:{fontWeight:700},gutterBottom:!0,children:"\uD83C\uDFF7️ 所有标签"}),(0,r.jsx)(s.default,{sx:{display:"flex",gap:2,flexWrap:"wrap",mt:2},children:n.map(n=>(0,r.jsx)(c.default,{label:"#".concat(n),component:"a",href:"/tags/".concat(n),clickable:!0,color:"primary",variant:"outlined",sx:{fontSize:"1rem",py:2.5,px:1}},n))})]})}},8883:(n,e,t)=>{"use strict";t.d(e,{Yl:()=>r,r:()=>a});let r=[{slug:"ai-tools-2026",title:"2026年最值得学的5个AI工具",date:"2026-05-10",description:"从ChatGPT到本地部署的大模型，这些AI工具正在改变我们的工作方式。",tags:["AI","工具","效率"],content:'\n人工智能正在重塑每个行业。无论你是开发者、设计师还是内容创作者，掌握这些AI工具都能让你的工作效率提升数倍。\n\n## 1. ChatGPT & Claude — 对话式AI助手\n\n这是目前最强大的通用AI助手。它们能：\n- 写代码、调试、解释复杂概念\n- 起草邮件、文章、报告\n- 分析数据、生成图表建议\n- 翻译和多语言处理\n\n**推荐用法**：把它们当作你的"第二大脑"，而不是替代品。\n\n## 2. Cursor / Copilot — AI编程助手\n\n对于开发者来说，这是革命性的工具：\n- **智能补全**：根据上下文自动补全代码\n- **自然语言编程**：用中文描述需求，直接生成代码\n- **Bug修复**：自动分析错误并建议修复方案\n- **代码重构**：一键优化代码结构\n\n## 3. Midjourney / DALL-E 3 — AI图像生成\n\n从文字到图像，创意无边界：\n- 品牌设计、社交媒体配图\n- 产品原型可视化\n- 艺术创作和概念设计\n\n## 4. Ollama — 本地AI部署\n\n想要隐私和速度？本地部署是答案：\n- 完全离线运行，数据不离开你的电脑\n- 支持 Llama 3、Mistral、CodeLlama 等开源模型\n- 一键安装，开箱即用\n\n## 5. Make.com / n8n — AI自动化工作流\n\n把AI和其他工具连接起来：\n- 自动化重复性任务\n- 跨平台数据同步\n- 智能触发和条件判断\n\n## 总结\n\nAI工具不是来抢你饭碗的，是来帮你干活的。选对工具，学会组合使用，你的生产力可以提升10倍。\n    '},{slug:"docker-guide",title:"Docker入门：10分钟搞懂容器化",date:"2026-05-10",description:"Docker是现代开发的必备技能。用最简单的方式理解容器化技术。",tags:["Docker","DevOps","容器化"],content:'\nDocker是目前最流行的容器化平台，它让应用的打包、分发和运行变得极其简单。\n\n## 什么是Docker？\n\n想象你有一个万能的行李箱：\n- **镜像（Image）**= 行李箱的模板\n- **容器（Container）**= 装好东西的行李箱\n- **Dockerfile**= 打包指南\n\nDocker让你把应用和它需要的一切（代码、运行时、系统库）打包成一个标准化的"集装箱"，在任何地方都能运行。\n\n## 为什么用Docker？\n\n1. **环境一致**：在我机器上能跑 = 在你机器上也能跑\n2. **快速部署**：几秒钟启动一个完整环境\n3. **资源高效**：比虚拟机轻量得多\n4. **版本管理**：轻松切换不同版本\n\n## 3个核心命令\n\n```bash\n# 拉取镜像\ndocker pull nginx\n\n# 运行容器\ndocker run -d -p 80:80 nginx\n\n# 查看运行中的容器\ndocker ps\n```\n\n## Docker Compose — 多容器管理\n\n```yaml\nversion: \'3\'\nservices:\n  web:\n    image: nginx\n    ports:\n      - "80:80"\n  db:\n    image: postgres\n    environment:\n      POSTGRES_PASSWORD: secret\n```\n\n一条命令启动整个栈：\n```bash\ndocker-compose up -d\n```\n\n## 总结\n\nDocker已经从"可选技能"变成了"必备技能"。花10分钟学会这3个命令，你就踏上了现代化开发的第一步。\n    '},{slug:"nextjs-guide",title:"Next.js全栈开发实战：从零到部署",date:"2026-05-09",description:"用Next.js构建现代Web应用的完整指南，包含TypeScript、API路由和部署。",tags:["Next.js","React","全栈"],content:"\nNext.js 是目前最流行的 React 框架，它让全栈开发变得简单高效。\n\n## 为什么选 Next.js？\n\n1. **服务端渲染（SSR）**：首屏加载快，SEO 好\n2. **API 路由**：前后端一体，不用单独写后端\n3. **文件系统路由**：目录结构就是路由结构\n4. **TypeScript 原生支持**：类型安全，减少 bug\n5. **零配置部署**：Vercel 一键上线\n\n## 快速开始\n\n```bash\nnpx create-next-app@latest my-app --typescript\ncd my-app\nnpm run dev\n```\n\n## App Router（推荐）\n\n```tsx\n// app/page.tsx - 首页\nexport default function Home() {\n  return <h1>欢迎来到我的网站</h1>\n}\n\n// app/blog/[slug]/page.tsx - 动态路由\nexport default function BlogPost({ params }: { params: { slug: string } }) {\n  return <h1>文章: {params.slug}</h1>\n}\n```\n\n## API 路由\n\n```tsx\n// app/api/hello/route.ts\nexport async function GET() {\n  return Response.json({ message: 'Hello World' })\n}\n```\n\n## 部署\n\n最简单的方式是用 Vercel：\n\n```bash\nnpm i -g vercel\nvercel\n```\n\n三步搞定，自动给你一个线上地址。\n\n## 总结\n\nNext.js 让前端开发者也能轻松做全栈。学会它，你就能独立开发完整的 Web 应用。\n    "}];function a(){let n=new Set;return r.forEach(e=>e.tags.forEach(e=>n.add(e))),Array.from(n)}}},n=>{n.O(0,[726,981,441,255,358],()=>n(n.s=6475)),_N_E=n.O()}]);